        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IPackageGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (obj.Location is IFormLinkContainerGetter LocationlinkCont)
            {
                foreach (var item in LocationlinkCont.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Location2 is IFormLinkContainerGetter Location2linkCont)
            {
                foreach (var item in Location2linkCont.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Target is IFormLinkContainerGetter TargetlinkCont)
            {
                foreach (var item in TargetlinkCont.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            foreach (var item in obj.Conditions.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (obj.IdleAnimations is {} IdleAnimationsItems)
            {
                foreach (var item in IdleAnimationsItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.CombatStyle, out var CombatStyleInfo))
            {
                yield return CombatStyleInfo;
            }
            if (obj.Target2 is IFormLinkContainerGetter Target2linkCont)
            {
                foreach (var item in Target2linkCont.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.DialogueData is {} DialogueDataItems)
            {
                foreach (var item in DialogueDataItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.DialogueLocation is IFormLinkContainerGetter DialogueLocationlinkCont)
            {
                foreach (var item in DialogueLocationlinkCont.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.OnBegin is {} OnBeginItems)
            {
                foreach (var item in OnBeginItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.OnEnd is {} OnEndItems)
            {
                foreach (var item in OnEndItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.OnChange is {} OnChangeItems)
            {
                foreach (var item in OnChangeItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            yield break;
        }
        
